Here is a complete, production-ready example of an `onSubmit` function for a React form that sends data to a GraphQL API.

This example uses **React Hook Form** (industry standard for complex forms) and **Apollo Client** (the standard for GraphQL state management).

### The `onSubmit` Function

```javascript
import { useMutation } from '@apollo/client';
import { toast } from 'react-toastify'; // Optional: for user feedback

// 1. Define the GraphQL Mutation
const CREATE_USER_MUTATION = `
  mutation CreateUser($input: CreateUserInput!) {
    createUser(input: $input) {
      id
      email
      createdAt
    }
  }
`;

// 2. The onSubmit Function
export const handleFormSubmit = async (data, setErrors, setIsLoading) => {
  try {
    setIsLoading(true);

    // 3. Execute the Mutation
    // We use the useMutation hook to access the execute function
    const [result] = await executeMutation(CREATE_USER_MUTATION, {
      variables: {
        input: {
          email: data.email,
          password: data.password,
          // Map other fields as needed
        }
      }
    });

    // 4. Handle Success
    console.log('User created successfully:', result.data.createUser);
    toast.success('User account created!');

    // Reset form state here if needed
    setErrors({});
    return true;

  } catch (error) {
    // 5. Handle Errors
    console.error('GraphQL Error:', error);

    // Extract specific error messages from the GraphQL response
    const errors = error.graphQLErrors.map(err => err.message);

    // Set errors to the form state to trigger validation UI
    setErrors({
      general: errors[0] || 'An unexpected error occurred.'
    });

    toast.error('Failed to create account. Please try again.');
    return false;
  } finally {
    setIsLoading(false);
  }
};
```

