class CouchbaseMigration {

  private val cluster = Cluster.create("localhost")
  private val bucket = cluster.openBucket("wisk-couchbase-bucket")

  def runMigration(): Unit = {
    // Define the query to get unique venue_ids
    val selectQuery = N1qlQuery.simple(
      "SELECT DISTINCT venue_id FROM `wisk-couchbase-bucket`._default._default"
    )

    // Execute the query
    val result: QueryResult = bucket.query(selectQuery)

    // Iterate over the results
    for (row <- result) {
      // Extract venue_id
      val venueId = row.value().getLong("venue_id")

      // Construct the update query
      // Note: We use the variable $venueId directly in the string interpolation
      // However, for safety in production, consider using parameterized queries if the SDK supports it,
      // or ensure the value is strictly sanitized.
      val updateQuery = s"""
        |UPDATE `wisk-couchbase-bucket`._default._default AS doc 
        |SET doc.id = CONCAT('item_variation_', TO_STRING(doc.venue_id), '_', TO_STRING(doc.data.id)), 
        |    doc.data.item_distributor_id = doc.data.id 
        |WHERE venue_id = $venueId AND doc.data.item_distributor_id IS MISSING
      """.stripMargin

      // Execute the update
      bucket.query(N1qlQuery.simple(updateQuery))
    }

    // Clean up resources
    bucket.close()
    cluster.disconnect()
  }
}

object MigrationRunner {
  def main(args: Array[String]): Unit = {
    val migration = new CouchbaseMigration()

    // Run the migration
    migration.runMigration()
  }
}
