export default function() {
  this.on('message', (event) => {
    const { fileContent, delimiter } = event.data;

    try {
      // 1. Parse the CSV
      const rows = parseCSV(fileContent, delimiter);

      // 2. Send the result back to the main thread
      this.postMessage({
        type: 'success',
        data: rows
      });
    } catch (error) {
      // 3. Send error back to main thread
      this.postMessage({
        type: 'error',
        message: error.message
      });
    }
  });
}

// Simple CSV Parser (handles basic cases)
function parseCSV(content, delimiter = ',') {
  const lines = content.split(/\r\n|\n/);
  const rows = [];

  for (const line of lines) {
    if (line.trim() === '') continue; // Skip empty lines

    // Basic regex split (for simple CSVs without complex quoting)
    // For production, consider a library like 'papa-parse'
    const row = line.split(delimiter);
    rows.push(row);
  }

  return rows;
}
