// Input: 1 feature, Output: 1 value
const model = tf.sequential();
model.add(tf.layers.dense({ units: 1, inputShape: [1] }));

// Compile the model with a learning rate
model.compile({
  optimizer: tf.train.sgd(0.01), // Stochastic Gradient Descent
  loss: 'meanSquaredError'
});

// 2. Online Learning Logic
// This function updates the model weights based on a single data point
async function trainOnline(dataPoint) {
  // Create a tensor for the input (x)
  const x = tf.tensor2d([dataPoint.x], [1, 1]);
  // Create a tensor for the target (y)
  const y = tf.tensor2d([dataPoint.y], [1, 1]);

  // Perform a single step of training
  // fit() returns the history of the training step
  const history = await model.fit(x, y, {
    epochs: 1,
    verbose: 0 // Suppress logs for cleaner output
  });

  // Clean up tensors to free memory
  x.dispose();
  y.dispose();

  return history.history.loss;
}

