  // 1. Define the Shadow DOM
  static get observedAttributes() {
    // We observe 'required' and 'list' because they are attribute-based on HTMLInputElement
    // but not always exposed as direct properties on the custom element class.
    return ['required', 'list'];
  }

  constructor() {
    super();

    // 2. Create and attach Shadow DOM
    // This encapsulates the structure, but blocks form communication by default.
    this.attachShadow({ mode: 'open' });

    // 3. Create the internal HTMLInputElement
    // This is the "single source of truth" for component state.
    this._input = document.createElement('input');
    this._input.type = 'text';

    // 4. Setup the Shadow DOM structure
    // Note: The label is a SIBLING of this component in the light DOM, 
    // not a child. This is crucial for accessibility (screen readers).
    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: block;
          width: 100%;
        }
        input {
          width: 100%;
          padding: 8px;
          border: 1px solid #ccc;
          border-radius: 4px;
          box-sizing: border-box;
        }
        .error-message {
          color: red;
          font-size: 0.875rem;
          margin-top: 4px;
          display: none;
        }
        .error-message.visible {
          display: block;
        }
      </style>
      <div class="input-wrapper">
        <input id="internal-input">
        <div id="error-message" class="error-message"></div>
      </div>
    `;

    // Connect the internal input to the shadow DOM
